package de.corporate.lc.user.api;
import de.corporate.lc.audit.service.AuditService;import de.corporate.lc.user.service.RoleService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/roles") public class RoleController {private final RoleService service;private final AuditService audit;public RoleController(RoleService service,AuditService audit){this.service=service;this.audit=audit;}@GetMapping public List<RoleView> all(){return service.all();}@GetMapping("/permissions")public List<PermissionView> permissions(){return service.permissions();}@org.springframework.transaction.annotation.Transactional @PostMapping public RoleView create(@Valid @RequestBody RoleRequest request,Authentication auth){RoleView role=service.create(request);audit.recordChangeInTransaction(auth,"ROLE_CREATED","ROLE",role.id(),role.name(),null,AdministrationAuditSnapshot.role(role));return role;}@org.springframework.transaction.annotation.Transactional @PutMapping("/{id}")public RoleView update(@PathVariable UUID id,@Valid @RequestBody RoleRequest request,Authentication auth){String before=AdministrationAuditSnapshot.role(service.getForAdministration(id));RoleView role=service.update(id,request);audit.recordChangeInTransaction(auth,"ROLE_UPDATED","ROLE",id,role.name(),before,AdministrationAuditSnapshot.role(role));return role;}@org.springframework.transaction.annotation.Transactional @DeleteMapping("/{id}")public ResponseEntity<Void> delete(@PathVariable UUID id,Authentication auth){String before=AdministrationAuditSnapshot.role(service.getForAdministration(id));service.delete(id);audit.recordChangeInTransaction(auth,"ROLE_DELETED","ROLE",id,"Rolle gelöscht",before,null);return ResponseEntity.noContent().build();}}
